$action=$argv[1];if(!in_array($action,array('inspect','apply','rollback'),true))exit(2);
$root=realpath($argv[2]);$release=realpath(__DIR__);if(!$root||!is_file($root.'/config.core.php')||strpos($release,$root.DIRECTORY_SEPARATOR)===0||$release===$root)exit(2);
if(function_exists('posix_geteuid')&&posix_geteuid()===0)exit(2);umask(0077);
$spec=json_decode(file_get_contents($release.'/release.json'),true);$manifest=json_decode(file_get_contents($release.'/manifest.json'),true);if(!$spec||!$manifest||!preg_match('/^direct-forms-[A-Za-z0-9]+$/',$spec['id']))exit(2);
$backup=dirname($root).'/.isipto-release-backups/'.$spec['id'];$journalFile=$backup.'/state.json';$state=is_file($journalFile)?json_decode(file_get_contents($journalFile),true):null;
require $root.'/core/config/config.inc.php';
$pdo=new PDO('mysql:host='.$database_server.';dbname='.$dbase.';charset=utf8',$database_user,$database_password,array(PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION));
$map=array('modTemplate'=>array('site_templates','templatename','content'),'modChunk'=>array('site_htmlsnippets','name','snippet'),'modSnippet'=>array('site_snippets','name','snippet'));$modx=null;
function normalizedHash($code){return hash('sha256',trim(str_replace("\r\n","\n",preg_replace('/^<\?php\s*/','',$code))));}
function safePath($f){global $root;if(!is_string($f)||!preg_match('~^(?:assets|images|roistat|core/components/bitrix24)/[A-Za-z0-9_./а-яА-ЯёЁ -]+$~u',$f)||strpos($f,'..')!==false||strpos($f,'\\')!==false)throw new RuntimeException('Unsafe payload path');$path=$root.'/'.$f;$parent=dirname($path);while(!file_exists($parent))$parent=dirname($parent);if(is_link($path)||realpath($parent)!==$root&&strpos(realpath($parent),$root.'/')!==0)throw new RuntimeException('Unexpected symlink or parent');return $path;}
function rowFor($o){global $pdo,$map,$table_prefix;if(!isset($map[$o['class']]))throw new RuntimeException('Unknown object type');$m=$map[$o['class']];$q=$pdo->prepare('SELECT * FROM `'.$table_prefix.$m[0].'` WHERE `'.$m[1].'`=?');$q->execute(array($o['name']));$rows=$q->fetchAll(PDO::FETCH_ASSOC);if(count($rows)>1)throw new RuntimeException('Duplicate MODX name');return $rows?$rows[0]:null;}
function effectiveCode($r,$class){global $map,$root;if(!empty($r['static'])&&!empty($r['static_file'])){$file=safePath($r['static_file']);if(!is_readable($file))throw new RuntimeException('Missing static source');return file_get_contents($file);}return $r[$map[$class][2]];}
function bootstrap(){global $modx,$root;if($modx)return;define('MODX_API_MODE',true);require $root.'/config.core.php';require MODX_CORE_PATH.'model/modx/modx.class.php';$modx=new modX();$modx->initialize('web');}
function retainGroup($file,$group){clearstatcache(true,$file);return filegroup($file)===$group||chgrp($file,$group);}
function refresh(){global $modx,$root;$results=array();$modx->cacheManager->refresh(array('resource'=>array('contexts'=>array('web')),'db'=>array(),'scripts'=>array()),$results);foreach($results as $partition=>$ok){if($ok!==false)continue;$key=$modx->getOption('cache_'.$partition.'_key',null,$partition);$dir=$modx->cacheManager->getCachePath().$key;if(file_exists($dir))throw new RuntimeException('Cache refresh failed: '.$partition);/* An absent partition has no stale files to clear. MODX returns false for it. */}$cache=realpath($root.'/core/cache');if($cache!==$root.'/core/cache')throw new RuntimeException('Unexpected cache path');$uid=function_exists('posix_geteuid')?posix_geteuid():-1;$group=filegroup($root.'/index.php');$it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($cache,FilesystemIterator::SKIP_DOTS),RecursiveIteratorIterator::SELF_FIRST,RecursiveIteratorIterator::CATCH_GET_CHILD);foreach($it as $e){if($e->isLink()||$e->getOwner()!==$uid)continue;if(!retainGroup($e->getPathname(),$group)||!chmod($e->getPathname(),$e->isDir()?0770:0660))throw new RuntimeException('Cannot retain cache access for web PHP');}}
function targetDirectory($dir){global $root;if(is_dir($dir))return;if(strpos($dir,$root.'/')!==0)throw new RuntimeException('Unsafe directory');targetDirectory(dirname($dir));if(!mkdir($dir,0770)||!retainGroup($dir,filegroup($root.'/index.php'))||!chmod($dir,0770))throw new RuntimeException('Cannot create accessible target directory');}
function journal(){global $state,$journalFile;$tmp=$journalFile.'.tmp';if(file_put_contents($tmp,json_encode($state,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),LOCK_EX)===false||!rename($tmp,$journalFile))throw new RuntimeException('Journal write failed');chmod($journalFile,0600);}
function rootSource(){global $modx;foreach($modx->getCollection('sources.modMediaSource') as $s){if($s->get('class_key')!=='sources.modFileMediaSource')continue;$props=$s->get('properties');if(is_string($props))$props=json_decode($props,true);$base=isset($props['basePath']['value'])?$props['basePath']['value']:'';if($base==='')return (int)$s->get('id');}throw new RuntimeException('No filesystem media source rooted at the site');}
function snapshotRows(){global $spec; $rows=array();foreach(array_merge($spec['objects'],$spec['removeObjects']) as $o)$rows[]=array('class'=>$o['class'],'name'=>$o['name'],'row'=>rowFor($o));return $rows;}
function checkPreflight(){global $spec,$manifest,$root,$release,$map;
 $errors=array();foreach($manifest as $m){$target=safePath($m['path']);$file=$release.'/payload/'.$m['path'];if(!is_file($file)||hash_file('sha256',$file)!==$m['sha256'])$errors[]='Payload hash mismatch: '.$m['path'];if(is_file($target)&&!in_array(hash_file('sha256',$target),$m['allowedBefore'],true))$errors[]='Unapproved hosting file difference: '.$m['path'];}
 foreach($spec['deleteFiles'] as $m){$target=safePath($m['path']);if(is_file($target)&&!in_array(hash_file('sha256',$target),$m['allowedBefore'],true))$errors[]='Unapproved obsolete file difference: '.$m['path'];}
 foreach(array_merge($spec['objects'],$spec['removeObjects']) as $o){$r=rowFor($o);if($r&&!in_array(normalizedHash(effectiveCode($r,$o['class'])),$o['allowedBefore'],true))$errors[]='Unapproved MODX difference: '.$o['class'].' / '.$o['name'];}
 foreach(array('AjaxForm','FormIt','FormItSaveForm') as $name)if(!rowFor(array('class'=>'modSnippet','name'=>$name)))$errors[]='Missing dependency: '.$name;
 $secret=dirname($root).'/'.$spec['secretRelativeToSiteParent'];if(!is_readable($secret))$errors[]='Hosting webhook secret is not configured';elseif(is_link($secret)||(fileperms($secret)&0007)!==0)$errors[]='Unsafe secret permissions';
 if(is_readable($secret)){require_once $release.'/payload/core/components/bitrix24/client.php';putenv('BITRIX24_ENV_FILE='.$secret);try{IsiptoBitrix24Client::fromEnvironment();}catch(Exception $e){$errors[]='Hosting webhook secret format is invalid';}}
 if(!function_exists('curl_init'))$errors[]='PHP cURL extension is missing';
 return $errors;
}
function rollbackSaved($allowPartial=false){global $state,$backup,$root,$pdo,$table_prefix,$map,$spec,$manifest;
 if(!$state||empty($state['rows']))throw new RuntimeException('No rollback journal');
 if(!$allowPartial){foreach($manifest as $m){$p=safePath($m['path']);if(!is_file($p)||hash_file('sha256',$p)!==$m['sha256'])throw new RuntimeException('Later file changes detected; manual rollback required');}foreach($spec['objects'] as $o){$r=rowFor($o);if(!$r||normalizedHash(effectiveCode($r,$o['class']))!==$o['codeHash'])throw new RuntimeException('Later MODX changes detected; manual rollback required');}}
 foreach($state['files'] as $f){$target=safePath($f['path']);if($f['existed']){if(!is_dir(dirname($target)))mkdir(dirname($target),0770,true);if(!copy($backup.'/files/'.$f['path'],$target))throw new RuntimeException('Could not restore file');chmod($target,$f['mode']);}elseif(is_file($target)&&!unlink($target))throw new RuntimeException('Could not remove new file');}
 foreach($state['rows'] as $e){$m=$map[$e['class']];$current=rowFor($e);$r=$e['row'];if(!$r){if($current){$q=$pdo->prepare('DELETE FROM `'.$table_prefix.$m[0].'` WHERE id=?');$q->execute(array($current['id']));}continue;}if(!$current){$cols=array_keys($r);$q=$pdo->prepare('INSERT INTO `'.$table_prefix.$m[0].'` (`'.implode('`,`',$cols).'`) VALUES ('.implode(',',array_fill(0,count($cols),'?')).')');$q->execute(array_values($r));}else{$fields=array($m[2],'static','static_file','source');$values=array();$sets=array();foreach($fields as $f){$sets[]='`'.$f.'`=?';$values[]=$r[$f];}$values[]=$current['id'];$q=$pdo->prepare('UPDATE `'.$table_prefix.$m[0].'` SET '.implode(',',$sets).' WHERE id=?');$q->execute($values);}}
 bootstrap();refresh();$state['phase']='rolled-back';$state['rollbackUtc']=gmdate('c');journal();
}
try{
 if($action==='rollback'){rollbackSaved();echo json_encode(array('phase'=>'rolled-back','databaseImported'=>false,'crmWrites'=>0))."\n";exit;}
 $errors=checkPreflight();if($action==='inspect'){echo json_encode(array('mode'=>'READ_ONLY','php'=>PHP_VERSION,'objects'=>count($spec['objects']),'files'=>count($manifest),'errors'=>$errors,'ready'=>!$errors,'crmWrites'=>0),JSON_UNESCAPED_UNICODE)."\n";exit($errors?1:0);}if($errors)throw new RuntimeException('Preflight rejected; run inspect');
 if($state)throw new RuntimeException('Release journal already exists; refusing repeated apply');
 if(!is_dir($backup)&&!mkdir($backup,0700,true))throw new RuntimeException('Cannot create private rollback directory');
 $state=array('id'=>$spec['id'],'phase'=>'backing-up','createdUtc'=>gmdate('c'),'rows'=>snapshotRows(),'files'=>array());
 $paths=array();foreach(array_merge($manifest,$spec['deleteFiles']) as $m)$paths[$m['path']]=true;
 foreach(array_keys($paths) as $f){$target=safePath($f);$exists=is_file($target);if($exists){$dest=$backup.'/files/'.$f;if(!is_dir(dirname($dest)))mkdir(dirname($dest),0700,true);if(!copy($target,$dest)||hash_file('sha256',$dest)!==hash_file('sha256',$target))throw new RuntimeException('Rollback copy failed');chmod($dest,0600);}$state['files'][]=array('path'=>$f,'existed'=>$exists,'mode'=>$exists?fileperms($target)&0777:0660);}
 journal();$state['phase']='applying';journal();umask(0007);
 foreach($manifest as $m){$target=safePath($m['path']);targetDirectory(dirname($target));$mode=is_file($target)?fileperms($target)&0777:0660;$tmp=$target.'.'.$spec['id'].'.partial';if(!copy($release.'/payload/'.$m['path'],$tmp)||hash_file('sha256',$tmp)!==$m['sha256']||!retainGroup($tmp,filegroup($root.'/index.php'))||!chmod($tmp,$mode)||!rename($tmp,$target))throw new RuntimeException('Atomic file install failed: '.$m['path']);}
 bootstrap();$source=rootSource();$objects=$spec['objects'];usort($objects,function($a,$b){$rank=array('modSnippet'=>0,'modChunk'=>1,'modTemplate'=>2);return $rank[$a['class']]-$rank[$b['class']];});
 foreach($objects as $o){$m=$map[$o['class']];$element=$modx->getObject($o['class'],array($m[1]=>$o['name']));if(!$element)$element=$modx->newObject($o['class']);$element->set($m[1],$o['name']);$element->set('static',$o['static']);$element->set('static_file',$o['static_file']);if($o['static'])$element->set('source',$source);$element->set($m[2],$o['code']);if(!$element->save())throw new RuntimeException('MODX save failed');if(normalizedHash($element->getContent())!==$o['codeHash'])throw new RuntimeException('MODX content verification failed');}
