}catch(Throwable $e){$reverted=false;if($state&&isset($state['phase'])&&$state['phase']==='applying'){try{rollbackSaved(true);$reverted=true;}catch(Throwable $r){fwrite(STDERR,"Automatic rollback incomplete; use private journal\n");}}fwrite(STDERR,json_encode(array('error'=>$e->getMessage(),'automaticallyRolledBack'=>$reverted),JSON_UNESCAPED_UNICODE)."\n");exit(1);}
